head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 페이지 로드 이벤트 핸들러(현재 별도 초기화 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 호출되는 페이지 언로드 이벤트 핸들러(현재 별도 정리 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 조회 완료 콜백 — 조회 결과 총 건수를 textbox_1에 표시한다.
 * @param {Number} rowcount 조회 결과 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount());
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10700.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description 달력 버튼 클릭 — 접수기준일자(txb_date) 입력용 달력 팝업(popUpCalendar)을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cal_onclick(e);
 */
scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10700.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description [조회] 버튼 클릭 — 접수일자(txb_date) 입력 확인 후 자동배포현황 목록을 조회한다(listSync).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_sys_search_onclick(e);
 */
scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.getValue() !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("접수일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10700.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description [엑셀다운로드] 버튼 클릭 — 자동배포현황 그리드(MxGrid_1)를 엑셀로 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_toExcel_onclick(e);
 */
scwin.btn_toExcel_onclick = function(e) {
    try {
        MxGrid_1.GridToExcel("자동배포현황", "", "8");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10700.btn_toExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 자동배포현황 목록 조회 — /autodst.do 서브미션으로 MxDataSet을 갱신하고 총 건수 표시 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.listSync();
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/autodst.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gform_onload
 * @description 구 gform onload 이관 — 초기 목록(/gauceSystemierAdaptor.do)을 조회해 총 건수 콜백을 연결하고 접수기준일자(txb_date)를 오늘로 설정한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

    // PanelToGroupBox_02(panel_2);

    toDaySet(txb_date);
};
